fn insert(oline: &Vec<char>, l: usize, nl: &Vec<char>, p: usize, at_pos: usize) -> Vec<char> {
    // We will build a new Vec<char> of length l + p
    let mut result = Vec::with_capacity(l + p);

    // 1) Copy the first `at_pos` characters of the original line
    result.extend_from_slice(&oline[..at_pos]);

    // 2) Copy the first `p` characters of the new line
    result.extend_from_slice(&nl[..p]);

    // 3) Copy the remaining characters of the original line,
    //    from `at_pos` up to `l`
    result.extend_from_slice(&oline[at_pos..l]);

    result
}

